      "expected": "All VSS and VSSA pins of the STM32F405 NAVC must be connected to the common GND net for the MCU to operate.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"144\") (name \"Net-(NAVC2-VSS-Pad18)\") (class \"Default\") (node (ref \"NAVC2\") (pin \"18\") (pinfunction \"VSS\") (pintype \"power_in\")) (node (ref \"NAVC2\") (pin \"63\") (pinfunction \"VSS\") (pintype \"passive\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"280\") (name \"unconnected-(NAVC2-VSSA-Pad12)\") (class \"Default\") (node (ref \"NAVC2\") (pin \"12\") (pinfunction \"VSSA\") (pintype \"power_in\")))"
        }
      ],
      "impact": "The NAVC has no ground return, so it cannot function.",
      "confidence": 1.0
    },
    {
      "category": "open_connection",
      "components": ["FCC2", "NAVC2", "REG1"],
